#[derive(Debug, Error)]
pub enum RepositoryError {
    #[error("{0}")]
    Validation(String),
    #[error("record not found")]
    NotFound,
    #[error("revision conflict: expected {expected}, current {current}")]
    RevisionConflict {
        expected: i64,
        current: i64,
        proposal: Value,
    },
    #[error("{0}")]
    Database(#[from] rusqlite::Error),
    #[error("{0}")]
    Serialization(#[from] serde_json::Error),
}

// A factual S08 lineage walk shares a per-read deadline, work ceiling and
// active-job set. It conveys no authority and rejects cycles or deep chains.
struct S08PolicyReadScope {active:std::collections::BTreeSet<String>, visits:usize, bytes:usize, rows:usize, deadline:std::time::Instant}
thread_local! {static S08_POLICY_READ_SCOPE:std::cell::RefCell<Option<S08PolicyReadScope>>=const {std::cell::RefCell::new(None)};}
struct S08PolicyReadRoot(bool);
impl S08PolicyReadRoot {
    fn enter()->Self {Self(S08_POLICY_READ_SCOPE.with(|slot|{let mut slot=slot.borrow_mut();if slot.is_some(){false}else{*slot=Some(S08PolicyReadScope{active:Default::default(),visits:0,bytes:0,rows:0,deadline:std::time::Instant::now()+std::time::Duration::from_secs(5)});true}}))}
}
impl Drop for S08PolicyReadRoot {fn drop(&mut self){if self.0 {S08_POLICY_READ_SCOPE.with(|slot|*slot.borrow_mut()=None);}}}
struct S08PolicyReadJob<'a> {key:String,conn:&'a Connection,previous_limit:i32}
// Charge borrowed SQLite values before converting them to owned Rust values.
// A policy walk also has a temporary SQLite per-value ceiling; the helper is a
// no-op for unrelated legacy reads.
pub(crate) fn s08_bounded_first<T:rusqlite::types::FromSql>(row:&rusqlite::Row<'_>,index:usize)->rusqlite::Result<T> {
    let active=S08_POLICY_READ_SCOPE.with(|slot|slot.borrow().as_ref().is_some_and(|s|!s.active.is_empty()));
    if active {
        let mut bytes=0usize;
        for i in 0..row.as_ref().column_count() {
            bytes=bytes.saturating_add(match row.get_ref(i)? {rusqlite::types::ValueRef::Text(v)|rusqlite::types::ValueRef::Blob(v)=>v.len(),_=>8});
        }
        let allowed=S08_POLICY_READ_SCOPE.with(|slot|{let mut slot=slot.borrow_mut();let Some(state)=slot.as_mut() else{return false};state.rows=state.rows.saturating_add(1);state.bytes=state.bytes.saturating_add(bytes);state.rows<=RESET_FENCE_ROWS && state.bytes<=RESET_FENCE_BYTES && state.deadline>std::time::Instant::now()});
        if !allowed {return Err(rusqlite::Error::InvalidQuery)}
    }
    row.get(index)
}
impl<'a> S08PolicyReadJob<'a> {
    fn enter(conn:&'a Connection,owner:&str,job:&str)->Result<Self,RepositoryError> {
        let key=format!("{}:{}:{}",owner.len(),owner,job);
        S08_POLICY_READ_SCOPE.with(|slot|{let mut slot=slot.borrow_mut();let state=slot.as_mut().ok_or(RepositoryError::NotFound)?;
            if state.active.len()>=8 || state.visits>=128 || state.deadline<=std::time::Instant::now() || !state.active.insert(key.clone()) {return Err(RepositoryError::NotFound)}
            state.visits+=1;Ok(())})?;
        // SAFETY: the owner holds this connection for the complete nested walk.
        let previous_limit=unsafe {rusqlite::ffi::sqlite3_limit(conn.handle(),rusqlite::ffi::SQLITE_LIMIT_LENGTH,-1)};
        unsafe {rusqlite::ffi::sqlite3_limit(conn.handle(),rusqlite::ffi::SQLITE_LIMIT_LENGTH,previous_limit.min(RESET_FENCE_VALUE_BYTES));}
        Ok(Self{key,conn,previous_limit})
    }
    fn charge_delta(rows:usize,bytes:usize)->Result<(),RepositoryError> {
        S08_POLICY_READ_SCOPE.with(|slot|{let mut slot=slot.borrow_mut();let state=slot.as_mut().ok_or(RepositoryError::NotFound)?;
            state.bytes=state.bytes.saturating_add(bytes);state.rows=state.rows.saturating_add(rows);
            if state.bytes>RESET_FENCE_BYTES || state.rows>RESET_FENCE_ROWS || state.deadline<=std::time::Instant::now() {Err(RepositoryError::NotFound)} else {Ok(())}})
    }
    fn charge(budget:&ResetFenceBudget)->Result<(),RepositoryError> {
        S08_POLICY_READ_SCOPE.with(|slot|{let mut slot=slot.borrow_mut();let state=slot.as_mut().ok_or(RepositoryError::NotFound)?;
            state.bytes=state.bytes.saturating_add(budget.bytes);state.rows=state.rows.saturating_add(budget.rows);
            if state.bytes>RESET_FENCE_BYTES || state.rows>RESET_FENCE_ROWS || state.deadline<=std::time::Instant::now() {Err(RepositoryError::NotFound)} else {Ok(())}})
    }
}
impl Drop for S08PolicyReadJob<'_> {fn drop(&mut self){
    // SAFETY: this guard never outlives its held owner connection.
    unsafe {rusqlite::ffi::sqlite3_limit(self.conn.handle(),rusqlite::ffi::SQLITE_LIMIT_LENGTH,self.previous_limit);}
    S08_POLICY_READ_SCOPE.with(|slot|{if let Some(state)=slot.borrow_mut().as_mut(){state.active.remove(&self.key);}});
}}

/// Original host-journal reset snapshot; this is not authority by itself.
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct ResetFenceBinding {
    pub account_id: String,
    pub operation_id: String,
    pub components: Vec<String>,
    pub expected_counts: Value,
    #[serde(default,skip_serializing_if="Option::is_none")]
    pub mode: Option<String>,
}

// These are safety ceilings, not expected latency or throughput guarantees.
const RESET_FENCE_VM_STEPS:usize=20_000_000;
const RESET_FENCE_ROWS:usize=100_000;
const RESET_FENCE_BYTES:usize=16*1024*1024;
const RESET_FENCE_VALUE_BYTES:i32=4*1024*1024;
const RESET_FENCE_TIME:std::time::Duration=std::time::Duration::from_secs(5);

pub(crate) struct ResetFenceBudget {
    // The exclusive connection mutex remains held and the connection outlives
    // this guard; no connection move occurs before Drop restores its settings.
    conn:*const Connection, previous_limit:i32, deadline:std::time::Instant,
    rows:usize, bytes:usize,
}
impl ResetFenceBudget {
    pub(crate) fn install(conn:&Connection)->Self {Self::install_bounded(conn,RESET_FENCE_TIME)}
    pub(crate) fn install_bounded(conn:&Connection,timeout:std::time::Duration)->Self {
        use std::sync::{Arc,atomic::{AtomicUsize,Ordering}};
        let deadline=std::time::Instant::now()+timeout.min(RESET_FENCE_TIME);
        let previous_limit=unsafe {rusqlite::ffi::sqlite3_limit(conn.handle(),rusqlite::ffi::SQLITE_LIMIT_LENGTH,-1)};
        unsafe {rusqlite::ffi::sqlite3_limit(conn.handle(),rusqlite::ffi::SQLITE_LIMIT_LENGTH,previous_limit.min(RESET_FENCE_VALUE_BYTES));}
        let steps=Arc::new(AtomicUsize::new(0));
        conn.progress_handler(128,Some(move || steps.fetch_add(128,Ordering::Relaxed)>=RESET_FENCE_VM_STEPS || std::time::Instant::now()>=deadline));
        Self{conn,previous_limit,deadline,rows:0,bytes:0}
    }
    // Read-only nested verification must not replace an outer progress handler.
    fn detached()->Self {Self{conn:std::ptr::null(),previous_limit:0,deadline:std::time::Instant::now()+RESET_FENCE_TIME,rows:0,bytes:0}}
    pub(crate) fn check(&mut self,bytes:usize)->Result<(),String> {
        if bytes>0 {self.rows=self.rows.saturating_add(1);self.bytes=self.bytes.saturating_add(bytes);}
        if self.rows>RESET_FENCE_ROWS || self.bytes>RESET_FENCE_BYTES || std::time::Instant::now()>=self.deadline {
            return Err("reset fence work budget exceeded".into());
        }
        Ok(())
    }
}
impl Drop for ResetFenceBudget {
    fn drop(&mut self) {
        if self.conn.is_null() {return;}
        // SAFETY: installation is private to the locked owner connection, and
        // this guard is dropped after its transaction and before that lock.
        let conn=unsafe{&*self.conn};
        conn.progress_handler(0,None::<fn()->bool>);
        unsafe {rusqlite::ffi::sqlite3_limit(conn.handle(),rusqlite::ffi::SQLITE_LIMIT_LENGTH,self.previous_limit);}
    }
}

fn check_reset_fence_binding(conn:&Transaction<'_>, owner:&str, account:&str, binding:&ResetFenceBinding, budget:&mut ResetFenceBudget)->Result<(),RepositoryError> {
    use crate::store::sqlite::SqliteStore;
    let unavailable=||RepositoryError::Validation("reset fence snapshot unavailable".into());
    if account.is_empty() || binding.account_id!=account || binding.operation_id.is_empty()
        || binding.operation_id.len()>512 || binding.operation_id.trim()!=binding.operation_id {return Err(unavailable());}
    let expanded=SqliteStore::normalize_reset_components(&binding.components).map_err(|_|unavailable())?;
    let expected=binding.expected_counts.as_object().ok_or_else(unavailable)?;
    if !expanded.iter().any(|v|v=="memories" || v=="ingest") || expected.len()!=expanded.len() || expanded.iter().any(|v|!expected.contains_key(v)) {return Err(unavailable());}
    let indexed=conn.query_row("SELECT EXISTS(SELECT 1 FROM sqlite_schema WHERE type='index' AND name='s08_consolidation_jobs')",[],|r|r.get::<_,bool>(0)).map_err(|_|unavailable())?;
    if !indexed {return Err(unavailable());}
    match binding.mode.as_deref() {
        None => {
            if expanded.iter().any(|v|v=="memories") {
                SqliteStore::reset_fence_lifecycle_in(conn,owner,account,true,false,budget).map_err(|_|unavailable())?;
            } else {
                SqliteStore::reset_fence_lifecycle_in(conn,owner,account,false,false,budget).map_err(|_|unavailable())?;
            }
            if conn.query_row("SELECT EXISTS(SELECT 1 FROM fm_v2_jobs INDEXED BY s08_consolidation_jobs WHERE owner_id=?1 AND kind='access_consolidation')",params![owner],|r|r.get::<_,bool>(0)).map_err(|_|unavailable())? {return Err(unavailable());}
        }
        Some("terminal-s08-v1") if binding.components.iter().any(|v|v=="memories") => {
            if SqliteStore::queued_lifecycle_pending(conn,owner).map_err(|_|unavailable())? {return Err(unavailable());}
            SqliteStore::reset_fence_lifecycle_in(conn,owner,account,true,true,budget).map_err(|_|unavailable())?;
        }
        _ => return Err(unavailable()),
    }
    let snapshot=SqliteStore::guarded_reset_components_in(conn,owner,account,&expanded,budget).map_err(|_|unavailable())?;
    if expanded.iter().any(|v|expected.get(v)!=snapshot.get(v)) {return Err(unavailable());}
    Ok(())
}

// The unconverted v2 writer must not silently bypass future v17 authority.
// Full trusted-context, receipt and provenance parity is still required.
fn require_legacy_knowledge_writer(transaction: &Transaction<'_>) -> Result<(), RepositoryError> {
    let version: i64 = transaction.query_row("PRAGMA user_version", [], |row| row.get(0))?;
    if version >= 17 {
        return Err(RepositoryError::Validation("guarded v17 knowledge writer unavailable".into()));
    }
    Ok(())
}

impl RepositoryError {
    pub fn code(&self) -> &'static str {
        match self {
            Self::Validation(_) => "validation",
            Self::NotFound => "not_found",
            Self::RevisionConflict { .. } => "revision_conflict",
            Self::Database(_) | Self::Serialization(_) => "storage_failure",
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
pub struct RevisionActor {
    pub actor_type: String,
    pub actor_id: String,
    pub reason: String,
    pub source_event_id: Option<String>,
}

impl RevisionActor {
    fn validate(&self) -> Result<(), RepositoryError> {
        if self.reason=="s04.queued-origin.v1" || self.source_event_id.as_deref().is_some_and(|id|reserved_queued_source(id,None,None)) {
            return Err(RepositoryError::Validation("queued source requires its private authority".into()));
        }
        for (name, value) in [
            ("actor_type", &self.actor_type),
            ("actor_id", &self.actor_id),
            ("reason", &self.reason),
        ] {
            if value.trim().is_empty() {
                return Err(RepositoryError::Validation(format!("{name} is required")));
            }
        }
        Ok(())
    }
}

pub(crate) fn reserved_provider_dossier(id:&str, uri:Option<&str>, kind:Option<&str>)->bool {
    id.starts_with("provider_dossier_") || uri.is_some_and(|value|value.starts_with("provider-dossier://"))
        || kind.is_some_and(|value|value == "provider_dossier.v1")
}

fn reserved_queued_source(id:&str,uri:Option<&str>,kind:Option<&str>)->bool {
    id.starts_with("queuedpart_") || uri.is_some_and(|value|value.starts_with("host-queued://"))
        || kind==Some("host_queued_part.v1")
}

