/// Exact reference copied from the existing S05 job, never model metadata.
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
pub struct HostArchiveSourceRef {
    pub version: u32, pub kind: String, pub account_id: String, pub chat_id: String,
    pub actor_id: String, pub message_id: String, pub part_id: String, pub revision: i64,
    pub content_hash: String,
    #[serde(deserialize_with="required_optional_string")]
    #[schemars(with="RequiredNullableString")]
    pub workspace_id: Option<String>,
    #[serde(deserialize_with="required_optional_string")]
    #[schemars(with="RequiredNullableString")]
    pub project_id: Option<String>,
}
fn required_optional_string<'de,D:serde::Deserializer<'de>>(deserializer:D)->Result<Option<String>,D::Error> {
    Option::<String>::deserialize(deserializer)
}
// Schemars' `required` attribute also removes null. This non-Option schema
// proxy keeps the field required while its value accepts a string or null.
struct RequiredNullableString;
impl JsonSchema for RequiredNullableString {
    fn inline_schema()->bool {true}
    fn schema_name()->std::borrow::Cow<'static,str> {"RequiredNullableString".into()}
    fn json_schema(generator:&mut schemars::SchemaGenerator)->schemars::Schema {
        <Option<String> as JsonSchema>::json_schema(generator)
    }
}

/// Closed queued-part identity. It is never interchangeable with a host user
/// body: archive and native hashes describe different immutable evidence.
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
pub struct QueuedArchiveSourceRef {
    pub version:u32,pub kind:String,pub account_id:String,pub chat_id:String,pub workspace_id:String,
    pub request_id:String,pub native_session_id:String,pub message_id:String,pub part_id:String,
    pub archive_revision:i64,pub archive_content_hash:String,pub text_sha256:String,pub ingress_sha256:String,
    pub root_operation_id:String,pub execution_revision:i64,pub inner_turn_id:String,
}

impl QueuedArchiveSourceRef {
    pub fn validate(&self)->Result<(),RepositoryError>{
        let ids=[&self.account_id,&self.chat_id,&self.workspace_id,&self.request_id,&self.native_session_id,
            &self.message_id,&self.part_id,&self.root_operation_id,&self.inner_turn_id];
        if self.version!=1 || self.kind!="queued_user_text" || self.archive_revision<1 || self.execution_revision<0
            || ids.iter().any(|v|v.is_empty() || v.trim()!=v.as_str() || v.len()>512)
            || [&self.chat_id,&self.message_id].iter().any(|v|!v.bytes().all(|b|(b'!'..=b'~').contains(&b)))
            || !valid_sha256(&self.archive_content_hash) || !valid_sha256(&self.text_sha256) || !valid_sha256(&self.ingress_sha256) {
            return Err(RepositoryError::Validation("queued source identity unavailable".into()));
        }
        Ok(())
    }
    pub fn stable_source_id(&self)->Result<String,RepositoryError>{
        self.validate()?;
        Ok(format!("queuedpart_{}",sha256_hex(&serde_json::to_vec(&("openclank.queued-source.v1",&self.account_id,
            &self.chat_id,&self.native_session_id,&self.request_id,&self.message_id,&self.part_id))?)))
    }
}

