pub(crate) fn analysis_snapshot_key<D>(request:&AnalysisSnapshotPublishRequest<D>)->Result<String,RepositoryError>{
    let domain=match request.version {1=>"openclank.analysis-snapshot-copy.v1",2=>"openclank.analysis-snapshot-copy.v2",_=>return Err(RepositoryError::NotFound)};
    Ok(format!("ma4_{}",sha256_hex(&serde_json::to_vec(&json!([domain,request.account_id,request.owner,request.workspace_id,request.capture_origin,request.manifest.manifest_sha256,request.manifest.capture_scope_sha256]))?)))
}

pub(crate) fn analysis_snapshot_request_json<D:Serialize>(request:&AnalysisSnapshotPublishRequest<D>)->Result<String,RepositoryError>{
    Ok(serde_json::to_string(&serde_json::to_value(request)?)?)
}

/// Closed analysis-provider profile table: (provider, producer_evidence, version_evidence).
/// Must mirror src/openclank/analysis_profiles.py PROFILES (lines 20-23). The snapshot gate
/// Version is checked together with this tuple below; legacy Rizin v1 bytes are unchanged.
const ANALYSIS_PROFILES:&[(&str,&str,&str)]=&[("rizin","native_producer_attested","operator_configured_unverified")];

fn analysis_profile_accepts(table:&[(&str,&str,&str)],provider:&str,producer_evidence:&str,version_evidence:&str)->bool{
    table.iter().any(|(p,pe,ve)|*p==provider && *pe==producer_evidence && *ve==version_evidence)
}

pub(crate) fn validate_analysis_snapshot<D:Serialize>(request:&AnalysisSnapshotPublishRequest<D>)->Result<(),RepositoryError>{
    let m=&request.manifest;let dossier:AnalysisSnapshotWireDossier=serde_json::from_value(serde_json::to_value(&request.dossier)?)?;
    let text=|v:&str,max:usize|!v.is_empty() && v.len()<=max && !v.chars().any(|c|c.is_control());
    let mut upload_parts=m.upload_id.split('.');
    let upload_stem=upload_parts.next().unwrap_or("");
    let extension=upload_parts.next();
    let upload_valid=upload_stem.len()==32 && upload_stem.bytes().all(|b|b.is_ascii_hexdigit()) && upload_parts.next().is_none() && extension.map_or(true,|v|!v.is_empty() && v.bytes().all(|b|b.is_ascii_alphanumeric()));
    if !matches!(request.version,1|2) || [&request.owner,&request.workspace_id,&request.account_id].iter().any(|v|!text(v,512) || v.trim()!=v.as_str()) || !text(&request.description,2048) || request.description.trim()!=request.description || !matches!(request.capture_origin.as_str(),"verified_capture"|"imported_unverified") || request.request_key!=analysis_snapshot_key(request)? || m.version!=1 || !upload_valid || !valid_sha256(&m.manifest_sha256) || !valid_sha256(&m.capture_scope_sha256) || !(1..=1048576).contains(&m.size_bytes) || m.media_type!="application/vnd.openclank.analysis-snapshot+json" || m.schema_version!=(if request.version==1 {"openclank.analysis-snapshot.v1"} else {"openclank.analysis-snapshot.v2"}) || !matches!(m.coverage.as_str(),"complete"|"selected"|"partial"|"unknown") || !(1..=1024).contains(&m.component_count) {return Err(RepositoryError::NotFound);}
    match (&dossier,request.version) {
        (AnalysisSnapshotWireDossier::Legacy(d),1)=>{
    if [&d.dossier_id,&d.source_id,&d.provider_version,&d.provider_evidence,&d.version_evidence].iter().any(|v|!text(v,512)) || !matches!(d.operation.as_str(),"functions"|"info"|"strings"|"disassembly"|"xrefs_to_entry"|"decompile"|"xrefs_from_instruction") || !d.interpretations.is_empty() || (!analysis_profile_accepts(ANALYSIS_PROFILES,&d.provider,&d.provider_evidence,&d.version_evidence) || d.provider!="rizin" || d.provider_version!="0.8.1") || !valid_sha256(&d.source_sha256) || !valid_sha256(&d.result_sha256) || !valid_sha256(&d.provider_sha256) || d.interpretations.len()>64 || d.interpretations.iter().any(|x|!text(&x.kind,128) || !valid_sha256(&x.sha256)) || [&d.dossier_revision,&d.source_revision].iter().any(|r|r.kind!="hostFingerprint" || !text(&r.value,256) || !r.value.starts_with("sha256:")) || !d.source_revision.value.starts_with(&format!("sha256:{}:",d.source_sha256)) {return Err(RepositoryError::NotFound);}
        },
        (AnalysisSnapshotWireDossier::Host(d),2)=>{
            if request.capture_origin!="verified_capture" || [&d.dossier_id,&d.source_id,&d.producer,&d.producer_version,&d.producer_evidence,&d.coverage,&d.payload_integrity].iter().any(|v|!text(v,512)) || d.operation!="info" || d.producer!="openclank.elf-metadata" || d.producer_version!="elf-v1-metadata-1" || d.producer_evidence!="host_owned_capture" || d.coverage!="partial_declared_metadata" || d.payload_integrity!="not_checked" || !d.interpretations.is_empty() || !valid_sha256(&d.source_sha256) || !valid_sha256(&d.result_sha256) || [&d.dossier_revision,&d.source_revision].iter().any(|r|r.kind!="hostFingerprint" || !text(&r.value,256) || !r.value.starts_with("sha256:")) || !d.source_revision.value.starts_with(&format!("sha256:{}:",d.source_sha256)) {return Err(RepositoryError::NotFound);}
        },
        _=>return Err(RepositoryError::NotFound),
    }
    Ok(())
}

pub(crate) fn analysis_snapshot_value<D:Serialize>(request:&AnalysisSnapshotPublishRequest<D>)->Result<String,RepositoryError>{
    validate_analysis_snapshot(request)?;
    let value=json!({"version":"openclank.analysis-snapshot-memory.v1","classification":"reviewed_procedural_data","capture_origin":request.capture_origin,"description":request.description,"dossier":request.dossier,"manifest":{"type":"attachment_ref","attachment_id":request.manifest.upload_id,"reference":request.manifest}});
    let raw=serde_json::to_string(&value)?;
    if raw.len()>16384 {return Err(RepositoryError::NotFound);}
    Ok(raw)
}

