// Sound only because `valid()` refuses NaN before a value is stored or compared.
impl Eq for FoundFeaturesV1 {}
impl FoundFeaturesV1 {
    pub const MAX_FTS_ORDINAL:u32=19;
    pub fn valid(&self)->bool {
        let unit=|v:&Option<f64>|v.is_none_or(|x|x.is_finite() && (0.0..=1.0).contains(&x));
        self.v==1 && self.fts_ordinal<=Self::MAX_FTS_ORDINAL
            && !self.route_kind.is_empty() && self.route_kind.len()<=32
            && self.route_kind.bytes().all(|b|b.is_ascii_lowercase() || b.is_ascii_digit() || b==b'_')
            && unit(&self.directness) && unit(&self.freshness)
    }
}
