fn s08_policy_accounting_valid(m:&S08ModelPrepareRequest)->bool {
    match (&m.importance_target,&m.selection.importance_target) {
        (None,None) if m.output_kind!="importance_target"=>{},
        (Some(target),Some(selected)) if m.output_kind=="importance_target"=>{
            if serde_json::to_value(target).ok()!=serde_json::to_value(selected).ok() || target.version!=1 || target.block_id.is_empty() || target.block_id.trim()!=target.block_id || target.block_id.len()>512 || target.expected_revision<1 || !valid_sha256(&target.value_sha256) || !valid_sha256(&target.source_commitment_sha256) || !valid_sha256(&target.policy_snapshot_sha256) || m.selection.journal.is_some() || m.selection.candidates.len()!=1 {return false;}
            let item=&m.selection.candidates[0];
            if item.block_id!=target.block_id || item.revision!=target.expected_revision || item.value_sha256!=target.value_sha256 || m.connection_predicate.is_some() {return false;}
            match (&*m.mode,&m.importance) {("rules",S08ImportanceDecision::Rules{..})=>{},("model"|"hybrid",S08ImportanceDecision::Managed{mode,..}) if mode==&m.mode=>{},_=>return false}
        },
        _=>return false,
    }
    if m.mode=="rules" {return m.connection_id=="local:rules" && m.model_route_id=="local:rules" && m.assignment_sha256==sha256_hex(b"no-model") && m.max_input_tokens==0 && m.max_output_tokens==0 && m.daily_calls==0 && m.daily_tokens==0}
    matches!(m.mode.as_str(),"model"|"hybrid") && !m.connection_id.is_empty() && m.connection_id.trim()==m.connection_id && m.connection_id.len()<=512 && m.connection_id!="local:rules" && !m.model_route_id.is_empty() && m.model_route_id.trim()==m.model_route_id && m.model_route_id.len()<=512 && m.max_input_tokens<=1000000 && (1..=32768).contains(&m.max_output_tokens) && (1..=1000000).contains(&m.daily_calls) && (1..=10000000).contains(&m.daily_tokens)
}
fn s08_importance_valid(primary:&str,value:&S08ImportanceDecision)->bool {
    match value {
        S08ImportanceDecision::Skipped{reason}=>matches!(reason.as_str(),"disabled"|"unset"|"unavailable"|"incompatible"),
        S08ImportanceDecision::Rules{value,provenance_sha256}=>value.is_finite() && (0.0..=1.0).contains(value) && valid_sha256(provenance_sha256),
        S08ImportanceDecision::Managed{mode,provenance_sha256}=>mode==primary && matches!(mode.as_str(),"model"|"hybrid") && valid_sha256(provenance_sha256),
    }
}
fn s08_importance_result(m:&S08ModelPrepareRequest,proposal:&Value,no_proposal:bool)->Result<(Option<f64>,Value),RepositoryError> {
    if !s08_importance_valid(&m.mode,&m.importance) {return Err(RepositoryError::NotFound)}
    if no_proposal {return Ok((None,json!({"state":"skipped","reason":"no_candidate"})))}
    match &m.importance {
        S08ImportanceDecision::Skipped{reason}=>{if proposal.get("importance_score").is_some() {return Err(RepositoryError::NotFound)}Ok((None,json!({"state":"skipped","reason":reason})))},
        S08ImportanceDecision::Rules{value,provenance_sha256}=>{if proposal.get("importance_score").is_some() {return Err(RepositoryError::NotFound)}Ok((Some(*value),json!({"state":"applied","mode":"rules","value":value,"provenance_sha256":provenance_sha256})))},
        S08ImportanceDecision::Managed{mode,provenance_sha256}=>match proposal.get("importance_score") {
            None|Some(Value::Null)=>Ok((None,json!({"state":"skipped","reason":"score_missing"}))),
            Some(v)=>{let score=v.as_f64().filter(|n|n.is_finite() && (0.0..=1.0).contains(n)).ok_or(RepositoryError::NotFound)?;Ok((Some(score),json!({"state":"applied","mode":mode,"value":score,"provenance_sha256":provenance_sha256})))},
        },
    }
}
/// Decode only a purpose-bound score for one exact selected target. This is
/// a factual result parser; no caller may infer review or write authority.
fn s08_importance_target_result(m:&S08ModelPrepareRequest,proposal:&Value,no_proposal:bool)->Result<Option<Value>,RepositoryError> {
    if m.output_kind!="importance_target" || m.connection_predicate.is_some() || !s08_importance_valid(&m.mode,&m.importance) {return Err(RepositoryError::NotFound)}
    let target=m.importance_target.as_ref().ok_or(RepositoryError::NotFound)?;
    let selected=m.selection.importance_target.as_ref().ok_or(RepositoryError::NotFound)?;
    if serde_json::to_value(target)?!=serde_json::to_value(selected)? || target.version!=1 || target.block_id.is_empty() || target.block_id.trim()!=target.block_id || target.block_id.len()>512 || target.expected_revision<1 || !valid_sha256(&target.value_sha256) || !valid_sha256(&target.source_commitment_sha256) || !valid_sha256(&target.policy_snapshot_sha256) {return Err(RepositoryError::NotFound)}
    if no_proposal {return Ok(None)}
    let identity=json!({"block_id":target.block_id,"expected_revision":target.expected_revision,"value_sha256":target.value_sha256,"source_commitment_sha256":target.source_commitment_sha256,"policy_snapshot_sha256":target.policy_snapshot_sha256});
    let score=match &m.importance {
        S08ImportanceDecision::Rules{value,..} if m.mode=="rules" && proposal.is_null()=>*value,
        S08ImportanceDecision::Managed{mode,..} if mode==&m.mode && proposal.as_object().map(|v|v.len())==Some(4) && proposal["version"]=="s08.importance-target.v1" && proposal["purpose"]=="importance_target" && proposal["target"]==identity=>proposal["score"].as_f64().filter(|v|v.is_finite() && (0.0..=1.0).contains(v)).ok_or(RepositoryError::NotFound)?,
        _=>return Err(RepositoryError::NotFound),
    };
    Ok(Some(json!({"version":"s08.importance-target.v1","purpose":"importance_target","target":identity,"score":score})))
}

fn s08_effective_importance(m:&S08ModelPrepareRequest,proposal:&Value,no_proposal:bool)->Result<(Option<f64>,Value),RepositoryError> {
    if m.output_kind!="importance_target" {return s08_importance_result(m,proposal,no_proposal)}
    if no_proposal {
        // A bound target result settled as unchanged retains its exact request
        // and charge; the current-target equality was checked before effects.
        let unchanged = if m.mode=="rules" { proposal==&json!({"version":1,"kind":"rules"}) }
            else { proposal!=&json!({"version":1,"kind":"no_proposal"}) };
        if unchanged {s08_importance_target_result(m,if m.mode=="rules" {&Value::Null} else {proposal},false)?.ok_or(RepositoryError::NotFound)?;}
        return Ok((None,json!({"state":"skipped","reason":if unchanged {"unchanged"} else {"no_candidate"}})))
    }
    let result=s08_importance_target_result(m,if m.mode=="rules" {&Value::Null} else {proposal},false)?;
    let Some(result)=result else {return Err(RepositoryError::NotFound)};
    let score=result["score"].as_f64().ok_or(RepositoryError::NotFound)?;
    let (mode,provenance)=match &m.importance {S08ImportanceDecision::Rules{provenance_sha256,..}=>("rules",provenance_sha256),S08ImportanceDecision::Managed{mode,provenance_sha256}=>(mode.as_str(),provenance_sha256),_=>return Err(RepositoryError::NotFound)};
    Ok((Some(score),json!({"state":"applied","mode":mode,"value":score,"provenance_sha256":provenance})))
}

/// Read the score only through the exact verified current target owner.  The
/// target commitment also fences revision, source, policy and custody.
fn s08_current_target_score(tx:&Transaction<'_>,m:&S08ModelPrepareRequest,view:&owner_custody::VerifiedCustodyView<'_,'_>,budget:&mut ResetFenceBudget)->Result<f64,RepositoryError> {
    let target=m.importance_target.as_ref().ok_or(RepositoryError::NotFound)?;
    let selection=&m.selection;
    let item=selection.candidates.first().filter(|_|selection.candidates.len()==1).ok_or(RepositoryError::NotFound)?;
    if item.block_id!=target.block_id || item.revision!=target.expected_revision {return Err(RepositoryError::NotFound)}
    let facts=s02_policy::importance_target_for_block_in(tx,&selection.owner,&selection.source_account_id,&selection.workspace_id,&item.block_id,item.revision,&m.policy_projection,view,budget)?;
    if facts["target"]!=serde_json::to_value(target)? {return Err(RepositoryError::NotFound)}
    facts["score_context"]["importance"]["value"].as_f64().filter(|n|n.is_finite() && (0.0..=1.0).contains(n)).ok_or(RepositoryError::NotFound)
}

/// Journal selections are one closed shape; every other selection keeps its original (admission/candidate) bounds at the call site.
fn s08_journal_selection_ok(selection:&S08RulesSelection,conn:&Connection)->bool {
    selection.journal.as_ref().is_some_and(|j|j.validate(selection).is_ok() && j.sourced().all(|r|r.source.as_ref().is_some_and(|s|s.account_id==selection.source_account_id && s.validate_in(conn).is_ok())))
}
/// Every archive source a selection depends on, with its authority: admissions for summary/connection, sourced rows for a journal.
fn s08_custody_sources(selection:&S08RulesSelection)->Vec<(&HostArchiveSourceRef,&ObservationOriginAuthority)> {
    let mut out:Vec<_>=selection.admissions.iter().map(|v|(&v.source,&v.authority)).collect();
    if let Some(j)=&selection.journal {for row in j.sourced() {if let (Some(s),Some(a))=(&row.source,&row.authority) {out.push((s,a));}}}
    out
}
/// A journal original is replayed (idempotently) only while it can still run; once it has an outcome, an issued attempt, or an
/// unverified cancellation the same key is never prepared again and `journal_delta_status` keeps answering the original.
fn s08_journal_replay_open(state:&str)->bool {matches!(state,"queued"|"retry_wait"|"active")}
fn s08_connection_predicate_valid(kind:&str,value:Option<&S08ConnectionPredicate>)->bool {
    match (kind,value) {("summary",None)|("importance_target",None)|(s08_journal::OUTPUT_KIND,None)=>true,("connection",Some(v))=>!v.predicate.is_empty() && v.predicate.trim()==v.predicate && v.predicate.len()<=512 && v.version>0 && valid_sha256(&v.sha256),_=>false}
}

