/// An internal borrowed proof; it is not a serializable authorization token.
pub(crate) struct VerifiedS08PolicyAttempt<'tx,'db> {tx:&'tx Transaction<'db>,view:owner_custody::VerifiedCustodyView<'tx,'db>,budget_id:*const ResetFenceBudget,request:S08ModelAttemptRequest}
impl<'tx,'db> VerifiedS08PolicyAttempt<'tx,'db> {
    pub(crate) fn revalidate(&self,tx:&Transaction<'_>,budget:&mut ResetFenceBudget)->Result<(),RepositoryError> {
        if !std::ptr::eq(self.tx,tx) || !std::ptr::eq(self.budget_id,budget as *const ResetFenceBudget) {return Err(RepositoryError::NotFound)}
        self.view.for_captured(tx,&self.request.original.selection.owner)?;
        V2Repository::verify_s08_policy_attempt(tx,&self.request,budget)
    }
    // The initial witness has already proved the complete selection in this
    // IMMEDIATE transaction. Only the disjoint target candidate rows are
    // inserted between these checkpoints; recheck every mutable authority
    // and the exact current target without replaying the same admissions.
    fn target_checkpoint(&self,tx:&Transaction<'_>,budget:&mut ResetFenceBudget)->Result<f64,RepositoryError> {
        if !std::ptr::eq(self.tx,tx) || !std::ptr::eq(self.budget_id,budget as *const ResetFenceBudget) || self.request.original.output_kind!="importance_target" {return Err(RepositoryError::NotFound)}
        let m=&self.request.original;let selection=&m.selection;
        self.view.for_captured(tx,&selection.owner)?;
        V2Repository::s08_model_attempt_reserve_fact(tx,&self.request,budget)?;
        s08_policy_lifecycle::deny_policy_reissue(tx,&selection.owner,&selection.source_account_id,m,&self.view,budget)?;
        deny_erased_import_job(tx,&selection.owner,&self.request.job_id,None)?;
        let input=sha256_hex(&serde_json::to_vec(selection)?);
        V2Repository::verify_s08_evidence(tx,&selection.owner,selection,&self.request.job_id,&input)?;
        let score=s08_current_target_score(tx,m,&self.view,budget)?;
        V2Repository::s08_attempt_live_lease(tx,&self.request)?;
        Ok(score)
    }
    pub(crate) fn selection(&self)->&S08RulesSelection {&self.request.original.selection}
    pub(crate) fn output_kind(&self)->&str {&self.request.original.output_kind}
    pub(crate) fn connection_predicate(&self)->Option<&S08ConnectionPredicate> {self.request.original.connection_predicate.as_ref()}
    pub(crate) fn job_id(&self)->&str {&self.request.job_id}
    pub(crate) fn attempt_id(&self)->&str {&self.request.attempt_id}
    pub(crate) fn lease_epoch(&self)->i64 {self.request.lease_epoch}
    pub(crate) fn canonical_evidence_for(&self,tx:&Transaction<'_>,events:&[String],budget:&mut ResetFenceBudget)->Result<Vec<String>,RepositoryError> {
        self.revalidate(tx,budget)?;let selection=self.selection();if events.is_empty() || events.len()>selection.admissions.len() {return Err(RepositoryError::NotFound)}
        let mut seen=BTreeSet::new();let mut evidence=BTreeSet::new();for event in events {
            budget.check(event.len()).map_err(RepositoryError::Validation)?;if !seen.insert(event) {return Err(RepositoryError::NotFound)}
            let item=selection.admissions.iter().find(|v|v.event_id==*event).ok_or(RepositoryError::NotFound)?;
            evidence.insert(format!("s08evidence_{}",sha256_hex(&serde_json::to_vec(&(&selection.owner,&self.request.job_id,&item.event_id))?)));
        }Ok(evidence.into_iter().collect())
    }
}

