/// Closed second contributor; its authority is supplied by the original Host pair owner.
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
pub struct AssistantInterpretationPart {
    pub message_id:String, pub part_id:String, pub revision:i64, pub content_hash:String,
}

#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
pub struct AssistantInterpretationCoverage {
    pub version:u32, pub kind:String, pub assistant:AssistantInterpretationPart, pub pair_sha256:String,
}
impl AssistantInterpretationCoverage {
    pub(crate) fn validate(&self, root:&HostArchiveSourceRef)->Result<(),RepositoryError> {
        root.validate()?;
        let a=&self.assistant;
        if self.version!=1 || self.kind!="assistant_interpretation_review" || !valid_sha256(&self.pair_sha256)
            || a.part_id!="body" || a.revision<1 || !valid_sha256(&a.content_hash)
            || a.message_id.is_empty() || a.message_id.len()>512 || a.message_id.trim()!=a.message_id
            || a.message_id==root.message_id || a.message_id.chars().any(char::is_control) {
            return Err(RepositoryError::Validation("assistant interpretation unavailable".into()));
        }
        Ok(())
    }
    pub(crate) fn source_key(&self, root:&HostArchiveSourceRef)->Result<String,RepositoryError> {
        self.validate(root)?;
        // Value maps use serde_json's ordered map; UTF-8 compact bytes match
        // the existing Host _exact_json contract, not a browser-provided hash.
        let bytes=serde_json::to_vec(&json!(["assistant_interpretation_review",root,self]))?;
        Ok(sha256_hex(&bytes))
    }
}

