/// Bound the rows reached by the existing explicit-question root owner before
/// it hydrates them. This is a resource preflight, never a proof of authority.
fn s09_explicit_root_preflight_in(tx:&Transaction<'_>,workspace:&str,curated:&str,id:&str,value:&Value,revision:&KnowledgeRevision,view:&owner_custody::VerifiedCustodyView<'_,'_>,budget:&mut ResetFenceBudget)->Result<(),RepositoryError>{
    let field=|name:&str|value.get(name).and_then(Value::as_str).filter(|v|!v.is_empty() && v.len()<=512).ok_or(RepositoryError::NotFound);
    let owner=view.current_owner();let account=field("account_id")?;let reviewer=field("owner")?;let candidate=field("candidate_id")?;let key=field("request_key")?;
    if account!=view.account_id() || field("workspace")?!=workspace || field("curated_id")?!=curated || field("block_id")?!=revision.identity.block_id {return Err(RepositoryError::NotFound)}
    view.for_captured(tx,reviewer)?;
    let digest=sha256_hex(&serde_json::to_vec(&("s03.explicit-add-id.v1",account,workspace,key))?);
    if candidate!=format!("manualadd_{digest}") {return Err(RepositoryError::NotFound)}
    let original=format!("cs_explicit_add_{digest}");let review=explicit_add::explicit_add_review_receipt_id(reviewer,workspace,account,candidate)?;let guard=&revision.change_set_id;let block=&revision.identity.block_id;let entity=&revision.identity.subject_entity_id;
    let evidence=format!("evidence_{curated}_1");let source=format!("source_memory_{}",&sha256_hex(&serde_json::to_vec(&json!([reviewer,curated]))?)[..32]);
    let root_rev=revision.revision;let two:&[&dyn rusqlite::ToSql]=&[&owner,&candidate];
    let charge=import_mirror::s09_charge_table_rows;
    charge(tx,"fm_v2_candidates","t","FROM fm_v2_candidates t WHERE t.owner_id=?1 AND t.candidate_id=?2",two,1,budget)?;
    charge(tx,"fm_v2_candidate_revisions","t","FROM fm_v2_candidate_revisions t WHERE t.owner_id=?1 AND t.candidate_id=?2 ORDER BY t.revision LIMIT 66",two,65,budget)?;
    charge(tx,"fm_v2_candidate_evidence","t","FROM fm_v2_candidate_evidence t WHERE t.owner_id=?1 AND t.candidate_id=?2 LIMIT 257",two,256,budget)?;
    charge(tx,"fm_v2_evidence","t","FROM fm_v2_evidence t JOIN fm_v2_candidate_evidence c ON c.owner_id=t.owner_id AND c.evidence_id=t.evidence_id WHERE c.owner_id=?1 AND c.candidate_id=?2 LIMIT 257",two,256,budget)?;
    charge(tx,"fm_v2_sources","t","FROM fm_v2_sources t JOIN fm_v2_evidence e ON e.owner_id=t.owner_id AND e.source_id=t.source_id AND e.source_revision=t.source_revision JOIN fm_v2_candidate_evidence c ON c.owner_id=e.owner_id AND c.evidence_id=e.evidence_id WHERE c.owner_id=?1 AND c.candidate_id=?2 LIMIT 257",two,256,budget)?;
    charge(tx,"fm_v2_sources","t","FROM fm_v2_sources t JOIN fm_v2_candidate_revisions r ON r.owner_id=t.owner_id AND r.source_id=t.source_id AND r.source_revision=t.source_revision WHERE r.owner_id=?1 AND r.candidate_id=?2 LIMIT 66",two,65,budget)?;
    charge(tx,"candidates","t","FROM candidates t WHERE t.owner=?1 AND t.id=?2",two,1,budget)?;
    let three:&[&dyn rusqlite::ToSql]=&[&owner,&block,&root_rev];
    charge(tx,"fm_v2_knowledge_blocks","t","FROM fm_v2_knowledge_blocks t WHERE t.owner_id=?1 AND t.block_id=?2",&[&owner,&block],1,budget)?;
    charge(tx,"fm_v2_knowledge_revisions","t","FROM fm_v2_knowledge_revisions t WHERE t.owner_id=?1 AND t.block_id=?2 AND t.revision=?3",three,1,budget)?;
    charge(tx,"fm_v2_revision_metadata","t","FROM fm_v2_revision_metadata t WHERE t.owner_id=?1 AND t.block_id=?2 AND t.revision=?3 LIMIT 257",three,256,budget)?;
    charge(tx,"fm_v2_revision_field_authority","t","FROM fm_v2_revision_field_authority t WHERE t.owner_id=?1 AND t.block_id=?2 AND t.revision=?3 LIMIT 257",three,256,budget)?;
    charge(tx,"fm_v2_revision_evidence","t","FROM fm_v2_revision_evidence t WHERE t.owner_id=?1 AND t.block_id=?2 AND t.revision=?3 LIMIT 257",three,256,budget)?;
    charge(tx,"fm_v2_evidence","t","FROM fm_v2_evidence t WHERE t.owner_id=?1 AND t.evidence_id=?2",&[&owner,&evidence],1,budget)?;
    charge(tx,"fm_v2_sources","t","FROM fm_v2_sources t WHERE t.owner_id=?1 AND t.source_id=?2 AND t.source_revision=1",&[&owner,&source],1,budget)?;
    charge(tx,"fm_v2_entities","t","FROM fm_v2_entities t WHERE t.owner_id=?1 AND t.entity_id=?2",&[&owner,&entity],1,budget)?;
    charge(tx,"fm_v2_entity_revisions","t","FROM fm_v2_entity_revisions t JOIN fm_v2_entities e ON e.owner_id=t.owner_id AND e.entity_id=t.entity_id AND e.current_revision=t.revision WHERE e.owner_id=?1 AND e.entity_id=?2",&[&owner,&entity],1,budget)?;
    charge(tx,"curated","t","FROM curated t WHERE t.owner=?1 AND t.workspace_id=?2 AND t.id=?3",&[&owner,&workspace,&curated],1,budget)?;
    let ids:&[&dyn rusqlite::ToSql]=&[&owner,&candidate,&original,&guard,&id,&review];
    charge(tx,"fm_v2_change_sets","t","FROM fm_v2_change_sets t WHERE t.owner_id=?1 AND (t.change_set_id IN (?3,?4,?5,?6) OR t.change_set_id IN (SELECT change_set_id FROM fm_v2_candidate_revisions WHERE owner_id=?1 AND candidate_id=?2)) LIMIT 69",ids,68,budget)?;
    charge(tx,"fm_v2_outbox","t","FROM fm_v2_outbox t WHERE t.owner_id=?1 AND (t.change_set_id IN (?3,?4,?5,?6) OR t.change_set_id IN (SELECT change_set_id FROM fm_v2_candidate_revisions WHERE owner_id=?1 AND candidate_id=?2)) LIMIT 137",ids,136,budget)?;
    Ok(())
}

