        if serde_json::to_string(&request)?!=receipt.request_json {return Err(RepositoryError::NotFound);}
        if request.version!=1 || request.owner!=owner || request.workspace_id!=workspace || request.account_id!=account || request.curated_id!=b.curated_id || request.predecessor_receipt_id!=receipt.predecessor_receipt_id || request.expected_revision!=receipt.expected_revision || request.request_key!=receipt.request_key || request.request_key!=account_value_successor_key(owner,workspace,&account,&b.block_id,receipt.expected_revision,&receipt.predecessor_receipt_id)? || !request.keep_prepared || request.operation_json!=receipt.operation_json {return Err(RepositoryError::NotFound);}
