    let first_length:Option<i64>=tx.query_row("SELECT length(CAST(operation_metadata_json AS BLOB)) FROM fm_v2_change_sets WHERE owner_id=? AND change_set_id=?",params![sql_owner,id],|r|r.get(0)).optional()?;
    if !first_length.is_some_and(|n|n>0 && n<=131072) {return Err(RepositoryError::NotFound);}
