            let mut decision_before=old_value.clone();if override_mode {decision_before.as_object_mut().ok_or(RepositoryError::NotFound)?.entry("policy_overrides").or_insert_with(||json!({}));}
            let changes=crate::field_authority::proposal_fields(&json!({"metadata":decision_before}),&json!({"metadata":actual})).map_err(RepositoryError::Validation)?;
            let mut paths=changes.iter().map(|v|v["path"].as_str().map(str::to_owned).ok_or(RepositoryError::NotFound)).collect::<Result<Vec<_>,_>>()?;paths.sort();let mut recorded=receipt.changed_paths.clone();recorded.sort();
