        let (revision,decision)=guarded_replay_custody_factual(tx,sql_owner,workspace,"",&b.block_id,&b.guarded_change_set_id,&receipt.operation_json,&receipt.operation_sha256,owner,view,phase,budget)?.ok_or(RepositoryError::NotFound)?;
        if revision.revision!=b.revision || decision["allowed_paths"]!=json!(["/value/value"]) {return Err(RepositoryError::NotFound);}
        let (identity,_,_,_)=read_knowledge_identity(tx,sql_owner,&b.block_id)?;
        let before=read_knowledge(tx,sql_owner,&identity,receipt.expected_revision,workspace,"")?;
        let old=serde_json::to_value(&before.payload.value)?; let new=serde_json::to_value(&revision.payload.value)?;
        if old["type"]!="string" || new["type"]!="string" || operation["payload"]["value"]!=new || sha256_hex(&serde_json::to_vec(&old)?)!=receipt.old_value_sha256 || sha256_hex(&serde_json::to_vec(&new)?)!=receipt.new_value_sha256 {return Err(RepositoryError::NotFound);}
        let mut prior_payload=serde_json::to_value(&before.payload)?; let next_payload=serde_json::to_value(&revision.payload)?;
