    #[test]
    fn job_attempts_are_fenced_and_history_is_append_only() {
        let mut conn = setup();
        let mut repository = V2Repository::new(&mut conn).unwrap();
        repository
            .create_job(
                &scope("alice"),
                "job-1",
                "extract",
                "job-key-1",
                "input-hash",
                &actor("queue"),
            )
            .unwrap();
        let (_, leased) = repository
            .claim_job(
                &scope("alice"),
                "job-1",
                "worker-1",
                "2999-01-01T00:00:00Z",
                &actor("claim"),
            )
            .unwrap();
        assert!(repository
            .start_job_attempt(
                &scope("alice"),
                "job-1",
                &leased.attempt_id,
                "worker-2",
                leased.lease_epoch,
                &actor("stale worker"),
            )
            .is_err());
        repository
            .start_job_attempt(
                &scope("alice"),
                "job-1",
                &leased.attempt_id,
                "worker-1",
                leased.lease_epoch,
                &actor("start"),
            )
            .unwrap();
        let completed = repository
            .finish_job(
                &scope("alice"),
                "job-1",
                &leased.attempt_id,
                "worker-1",
                leased.lease_epoch,
                JobState::Succeeded,
                Some(&json!({"count": 1})),
                None,
                &actor("finish"),
            )
            .unwrap();
        assert_eq!(completed.state, JobState::Succeeded);
        assert_eq!(
            repository
                .job_history(&scope("alice"), "job-1")
                .unwrap()
                .iter()
                .map(|event| event.state)
                .collect::<Vec<_>>(),
            vec![
                JobState::Queued,
                JobState::Active,
                JobState::Active,
                JobState::Succeeded
            ]
        );
        assert!(repository
            .finish_job(
                &scope("alice"),
                "job-1",
                &leased.attempt_id,
                "worker-1",
                leased.lease_epoch,
                JobState::Succeeded,
                None,
                None,
                &actor("retry stale"),
            )
            .is_err());
    }

    #[test]
    fn conflicts_preserve_the_head_until_atomic_resolution() {
        let mut conn = setup();
        let mut repository = V2Repository::new(&mut conn).unwrap();
        repository
            .create_entity(&scope("alice"), "entity-db", &entity(), &actor("create"))
            .unwrap();
        let identity = KnowledgeIdentity {
            block_id: "block-db".into(),
            subject_entity_id: "entity-db".into(),
            predicate: "definition".into(),
            claim_slot: "definition".into(),
            cardinality: PredicateCardinality::Single,
        };
        repository
            .create_knowledge(
                &scope("alice"),
                &identity,
                &knowledge("accepted"),
                &actor("create"),
            )
            .unwrap();
        repository
            .record_conflict(
                &scope("alice"),
                "conflict-1",
                "block-db",
                1,
                &json!({"value": {"type": "string", "value": "competing"}}),
                "sources disagree",
                &actor("record conflict"),
            )
            .unwrap();
        assert_eq!(
            repository
                .get_knowledge(&scope("alice"), "block-db", None)
                .unwrap()
                .revision,
            1
        );
        let resolved = repository
            .resolve_conflict(
                &scope("alice"),
                "conflict-1",
                1,
                &knowledge("resolved"),
                "human chose the supported value",
                &actor("resolve"),
            )
            .unwrap();
        assert_eq!(resolved.revision, 2);
        assert_eq!(
            repository
                .conflict_history(&scope("alice"), "conflict-1")
                .unwrap()
                .iter()
                .map(|event| event.state.as_str())
                .collect::<Vec<_>>(),
            vec!["open", "resolved"]
        );
    }

    #[test]
    fn authorized_source_erasure_is_atomic_and_owner_scoped() {
        let mut conn = setup();
        let mut repository = V2Repository::new(&mut conn).unwrap();
        for owner in ["alice", "bob"] {
            repository
                .create_source(&scope(owner), "source-1", 1, &source(), &actor("source"))
                .unwrap();
            repository
                .create_evidence(&scope(owner), "evidence-1", &evidence(), &actor("evidence"))
                .unwrap();
            repository
                .create_entity(&scope(owner), "entity-db", &entity(), &actor("entity"))
                .unwrap();
            let identity = KnowledgeIdentity {
                block_id: "block-db".into(),
                subject_entity_id: "entity-db".into(),
                predicate: "definition".into(),
                claim_slot: "definition".into(),
                cardinality: PredicateCardinality::Single,
            };
            let mut payload = knowledge("private value");
            payload.evidence_ids = vec!["evidence-1".into()];
            repository
                .create_knowledge(&scope(owner), &identity, &payload, &actor("knowledge"))
                .unwrap();
            repository
                .create_candidate(
                    &scope(owner),
                    "candidate-1",
                    "candidate-key-1",
                    &candidate(CandidateState::Proposed),
                    &actor("candidate"),
                )
                .unwrap();
        }
        let result = repository
            .erase_source(
                &scope("alice"),
                "source-1",
                &actor("authorized source forget"),
            )
            .unwrap();
        assert_eq!(result.erased_counts["sources"], 1);
        assert_eq!(result.erased_counts["knowledge_blocks"], 1);
        assert_eq!(result.erased_counts["candidates"], 1);
        assert!(matches!(
            repository.get_source(&scope("alice"), "source-1", 1),
            Err(RepositoryError::NotFound)
        ));
        assert_eq!(
            repository
                .get_source(&scope("bob"), "source-1", 1)
                .unwrap()
                .payload
                .content_hash,
            "source-content-hash"
        );
        assert_eq!(
            repository
                .conn
                .query_row(
                    "SELECT count(*) FROM fm_v2_privacy_erasure_context",
                    [],
                    |row| row.get::<_, i64>(0),
                )
                .unwrap(),
            0
        );
        assert!(repository
            .conn
            .execute(
                "DELETE FROM fm_v2_knowledge_revisions WHERE owner_id='bob'",
                [],
            )
            .unwrap_err()
            .to_string()
            .contains("append-only"));
    }

